const themeKeys=(['background','surface','sidebar','text','muted','accent'] as const);
function cleanTheme(value:any):ThemeConfig{const fallback=themePresets[0];const out={...fallback};for(const k of themeKeys)if(typeof value?.[k]==='string'&&/^#[0-9a-f]{6}$/i.test(value[k]))out[k]=value[k];out.border=typeof value?.border==='string'&&/^#[0-9a-f]{6}$/i.test(value.border)?value.border:out.text;const strength=Number(value?.borderStrength),radius=Number(value?.radius);if(Number.isFinite(strength))out.borderStrength=Math.min(40,Math.max(0,strength));if(Number.isFinite(radius))out.radius=Math.min(22,Math.max(2,radius));return out;}
function contrastFor(hex:string){const v=hex.replace('#','');const c=[0,2,4].map(i=>parseInt(v.slice(i,i+2),16)/255).map(x=>x<=.03928?x/12.92:((x+.055)/1.055)**2.4);return .2126*c[0]+.7152*c[1]+.0722*c[2]>.46?'#172019':'#ffffff';}
